mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g5-2/bot.mjs";
const T = 1767272400; // inbound, seconds
const at = (s) => new Date((T + s) * 1000);
const H = 3600;
const c = (optedIn, lastInboundTimestamp) => ({ optedIn, lastInboundTimestamp });
const cases = [
  ["text, in window (1h)", { type: "text", contact: c(true, String(T)) }, at(1*H), { allowed: true, reason: null }],
  ["text, 23h59m59s", { type: "text", contact: c(true, String(T)) }, at(24*H - 1), { allowed: true, reason: null }],
  ["text, exactly 24h", { type: "text", contact: c(true, String(T)) }, at(24*H), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, 3 days", { type: "text", contact: c(true, String(T)) }, at(72*H), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, never wrote (null)", { type: "text", contact: c(true, null) }, at(0), { allowed: false, reason: "no_customer_service_window" }],
  ["text, not opted in + window open", { type: "text", contact: c(false, String(T)) }, at(H), { allowed: false, reason: "contact_not_opted_in" }],
  ["text, inbound in future", { type: "text", contact: c(true, String(T + 60)) }, at(0), { allowed: false, reason: "inbound_timestamp_in_future" }],
  ["text, ms-string timestamp (treated invalid)", { type: "text", contact: c(true, String(T * 1000)) }, at(H), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, malformed timestamp", { type: "text", contact: c(true, "abc") }, at(H), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["text, numeric (not string) timestamp", { type: "text", contact: c(true, T) }, at(H), { allowed: false, reason: "invalid_inbound_timestamp" }],
  ["template, never wrote, opted in", { type: "template", contact: c(true, null) }, at(0), { allowed: true, reason: null }],
  ["template, window closed, opted in", { type: "template", contact: c(true, String(T)) }, at(100*H), { allowed: true, reason: null }],
  ["template, not opted in", { type: "template", contact: c(false, null) }, at(0), { allowed: false, reason: "contact_not_opted_in" }],
  ["unknown type", { type: "image", contact: c(true, String(T)) }, at(H), { allowed: false, reason: "unsupported_message_type" }],
  ["missing contact", { type: "template" }, at(0), { allowed: false, reason: "contact_not_opted_in" }],
  ["invalid now", { type: "text", contact: c(true, String(T)) }, new Date("nope"), { allowed: false, reason: "invalid_now" }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = decideWhatsApp(msg, now);
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
console.log(fail ? `${fail} FAILED` : "all passed");
process.exit(fail ? 1 : 0);
EOF
